<?php declare(strict_types=1); require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('PUT','POST');apiCsrf();$uid=apiAuth(['supplier','manufacturer','admin']);$in=apiInput();$id=apiId($in['id']??$_GET['id']??0);$db=apiDb();$s=$db->prepare('SELECT p.* FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id WHERE p.id=? AND (s.user_id=? OR ?="admin")');$s->execute([$id,$uid,currentRole()]);if(!$s->fetch())apiError('Not found',404);
$allowed=['name','description','sku','retail_price','wholesale_price','minimum_order_quantity','unit','category_id','status'];$set=[];$v=[];foreach($allowed as $k)if(array_key_exists($k,$in)){$set[]="$k=?";$v[]=$in[$k];}if(!$set)apiError('No changes',422);$v[]=$id;try{$db->prepare('UPDATE products SET '.implode(',',$set).' WHERE id=?')->execute($v);apiResponse(['id'=>$id]);}catch(Throwable $e){apiException($e);}